"""Exploratory Layfield-style type regressions; see recorded convention and limitations."""
import json, math, random, hashlib
from collections import Counter, defaultdict
from vs import corpus, ivtff, refcorpus

N=30000; SHUFFLES=49; SEED=41067
BOOKS=('it_dante','es_buenamor','en_paston','medieval_czech_01473c19')

def sample_witness(name):
 train,_=corpus.split_pages('practice',name)
 words=[w for p in train for ln in p.lines for w in ln.words if not ivtff.uncertain(w)
        and w.isascii() and w.isalpha() and w.islower()]
 assert len(words)>=N
 return words[:N]

def regress(x,y):
 if len(x)<30: return None
 mx=sum(x)/len(x);my=sum(y)/len(y)
 vx=sum((z-mx)**2 for z in x);vy=sum((z-my)**2 for z in y)
 if not vx or not vy: return None
 cov=sum((a-mx)*(b-my) for a,b in zip(x,y))
 return {'n':len(x),'slope':cov/vx,'r':cov/math.sqrt(vx*vy)}

def measures(counts):
 total=sum(counts.values()); token_prefix=Counter(); type_prefix=Counter()
 token_prefix['']=total
 for w,c in counts.items():
  for i in range(1,len(w)+1): token_prefix[w[:i]]+=c;type_prefix[w[:i]]+=1
 data=defaultdict(lambda:{'x':[],'u':[],'ix':[],'info':[],'no_internal_up':0,'no_finite_info':0})
 for w,c in counts.items():
  length=len(w)
  if not 4<=length<=8: continue
  up=next((i for i in range(1,length+1) if type_prefix[w[:i]]==1),length+1)
  # Equation (2) subtracts the complete word count. The UP itself has zero
  # competing-token numerator; exclude all undefined terms rather than invent smoothing.
  vals=[]
  for i in range(1,min(up,length+1)):
   num=token_prefix[w[:i]]-c;den=token_prefix[w[:i-1]]-c
   if num>0 and den>0: vals.append(-math.log2(num/den))
  d=data[length];x=math.log2(c/total);d['x'].append(x);d['u'].append(up/length)
  if up>length:d['no_internal_up']+=1
  if vals:d['ix'].append(x);d['info'].append(sum(vals)/len(vals))
  else:d['no_finite_info']+=1
 out={}
 for length,d in data.items():
  out[str(length)]={'uniqueness':regress(d['x'],d['u']), 'finite_pre_up_information':regress(d['ix'],d['info']),
                    'types':len(d['x']),'boundary_only_types':d['no_internal_up'],'omitted_info_types':d['no_finite_info']}
 return out

def experiment(words):
 counts=Counter(words); observed=measures(counts); bylen=defaultdict(list)
 for w in counts:bylen[len(w)].append(w)
 rng=random.Random(SEED);null=defaultdict(list)
 for _ in range(SHUFFLES):
  shuffled={}
  for types in bylen.values():
   vals=[counts[w] for w in types];rng.shuffle(vals);shuffled.update(zip(types,vals))
  m=measures(shuffled)
  for l,row in m.items():
   for metric in ('uniqueness','finite_pre_up_information'):
    if row[metric] is not None:null[l,metric].append(row[metric]['slope'])
 for l,row in observed.items():
  for metric in ('uniqueness','finite_pre_up_information'):
   val=row[metric];ns=null[l,metric]
   if val and ns:
    val['shuffle_range']=[min(ns),max(ns)]
    val['shuffle_direction']='greater' if metric=='uniqueness' else 'less'
    val['shuffle_directional_p']=(1+sum((x>=val['slope']) if metric=='uniqueness' else (x<=val['slope']) for x in ns))/(len(ns)+1)
 return {'tokens':len(words),'types':len(counts),'lengths':observed}

if __name__=='__main__':
 pins={e['id']:e for e in refcorpus.pins()}
 for b in BOOKS:
  with open(pins[b]['file'],'rb') as f: assert hashlib.sha256(f.read()).hexdigest()==pins[b]['sha256'], b
 results={}
 for w in ('zl','it'):
  path={'zl':'data/raw/ZL3b-n.txt','it':'data/raw/IT2a-n.txt'}[w]
  expected={'zl':'bf5b6d4ac1e3a51b1847a9c388318d609020441ccd56984c901c32b09beccafc','it':'7f27a8b0feed8f6de0a99900df6bf912dd1d295c38e5f830bac8b41c3f536fb5'}[w]
  with open(path,'rb') as f: assert hashlib.sha256(f.read()).hexdigest()==expected
  results[w]=experiment(sample_witness(w))
 for b in BOOKS:
  words=' '.join(refcorpus.blocks_of(b)).split();assert len(words)>=3*N
  for i in range(3): results[b+'_window'+str(i+1)]=experiment(words[i*N:(i+1)*N])
 print(json.dumps({'N':N,'shuffles':SHUFFLES,'seed':SEED,'results':results},indent=2))
